#!/usr/bin/env python3
"""Differential fixtures generated by the untouched original ARM functions."""
from pathlib import Path
from unicorn import Uc,UC_ARCH_ARM,UC_MODE_ARM
from unicorn.arm_const import *
from elftools.elf.elffile import ELFFile
import hashlib,json,random,struct
root=Path(__file__).resolve().parents[1]
path=root/'analysis/game-apk/lib/armeabi-v7a/libOrderUp.so'
f=path.open('rb');elf=ELFFile(f);u=Uc(UC_ARCH_ARM,UC_MODE_ARM)
u.mem_map(0,0x500000);u.mem_map(0x700000,0x10000);u.mem_map(0x20000000,0x100000);u.mem_map(0xf000000,4096)
for segment in elf.iter_segments():
 if segment['p_type']=='PT_LOAD':u.mem_write(segment['p_vaddr'],segment.data())
regs=[UC_ARM_REG_R0,UC_ARM_REG_R1,UC_ARM_REG_R2,UC_ARM_REG_R3]
def call(address,args):
 u.reg_write(UC_ARM_REG_CPSR,0x10);u.reg_write(UC_ARM_REG_SP,0x200fff00);u.reg_write(UC_ARM_REG_LR,0xf000000)
 for reg,value in zip(regs,args):u.reg_write(reg,value&0xffffffff)
 u.emu_start(address,0xf000000,count=3000000)
 assert u.reg_read(UC_ARM_REG_PC)==0xf000000
 return u.reg_read(UC_ARM_REG_R0)
rng=random.Random(20261103);audio=[]
for predictor in [0,0x7f,0x80,0xff]:
 for index in [0,1,20,88]:
  for volume in [-100,0,1,28,100,200,1000000000]:
   for samples in [0,2,28,30,64,127]:
    source=bytes([predictor,rng.randrange(256),index])+bytes(rng.getrandbits(8) for _ in range(samples//2))
    initial=bytes(rng.getrandbits(8) for _ in range((samples+4)*2));u.mem_write(0x700000,source);u.mem_write(0x701000,initial)
    call(0x38f5d4,[0x700000,0x701000,volume,samples]);expected=bytes(u.mem_read(0x701000,len(initial)))
    audio.append(dict(input=source.hex(),initial=initial.hex(),volume=volume,samples=samples,expected=expected.hex()))
fonts=[];font_cases=[]
for last in [0,1,3,16,96,255,512]:
 for underscore in [False,True]:
  characters=sorted(rng.sample([x for x in range(65536) if x!=95],last+1))
  if underscore:characters[last//2]=95;characters=sorted(characters)
  font=bytearray(128);struct.pack_into('<H',font,24,last);struct.pack_into('<I',font,60,0x704000)
  u.mem_write(0x703000,bytes(font));u.mem_write(0x704000,struct.pack('<'+'H'*len(characters),*characters));number=len(fonts);fonts.append(characters)
  for character in characters[:30]+[0,32,65,90,95,127,65535,65536,0xffffffff]+[rng.randrange(65536) for _ in range(30)]:
   expected=call(0x365cac,[0x703000,character]);font_cases.append(dict(font=number,character=character,expected=expected))
report=dict(binary_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),audio=audio,fonts=fonts,font_cases=font_cases)
(root/'analysis/hot-native-vectors.json').write_text(json.dumps(report,separators=(',',':'))+'\n')
print(len(audio),'original audio blocks and',len(font_cases),'original font lookups recorded.')
